Below is a React + TypeScript `Input` component that:

- Accepts user input.
- Shows a dropdown with filtered options as the user types.
- Hides the dropdown if there are no matches.
- Validates the input (red border if invalid).
- Handles edge cases (empty input, keyboard navigation, outside clicks).
- Optimizes for large option lists using virtualization (`react-window`).

**Install dependency:**
```bash
npm install react-window
```

**Input.tsx**
```tsx
import React, { useState, useRef, useEffect, ChangeEvent, KeyboardEvent } from 'react';
import { FixedSizeList as List } from 'react-window';

interface InputProps {
  options: string[];
  placeholder?: string;
  onChange?: (value: string) => void;
}

const ITEM_HEIGHT = 36;
const MAX_VISIBLE = 6;

export const Input: React.FC<InputProps> = ({ options, placeholder, onChange }) => {
  const [value, setValue] = useState('');
  const [filtered, setFiltered] = useState<string[]>([]);
  const [showDropdown, setShowDropdown] = useState(false);
  const [highlight, setHighlight] = useState(-1);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (value.trim() === '') {
      setFiltered([]);
      setShowDropdown(false);
      setHighlight(-1);
      return;
    }
    const f = options.filter(opt => opt.toLowerCase().includes(value.toLowerCase()));
    setFiltered(f);
    setShowDropdown(f.length > 0);
    setHighlight(-1);
  }, [value, options]);

  // Validation: must match an option exactly (case-insensitive)
  const isValid = options.some(opt => opt.toLowerCase() === value.trim().toLowerCase());

  // Outside click
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setShowDropdown(false);
        setHighlight(-1);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    setValue(e.target.value);
    onChange?.(e.target.value);
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (!showDropdown || filtered.length === 0) return;
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setHighlight(h => (h < filtered.length - 1 ? h + 1 : 0));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setHighlight(h => (h > 0 ? h - 1 : filtered.length - 1));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (highlight >= 0 && highlight < filtered.length) {
        setValue(filtered[highlight]);
        onChange?.(filtered[highlight]);
        setShowDropdown(false);
      }
    } else if (e.key === 'Escape') {
      setShowDropdown(false);
      setHighlight(-1);
    }
  };

  const handleOptionClick = (opt: string) => {
    setValue(opt);
    onChange?.(opt);
    setShowDropdown(false);
  };

  return (
    <div ref={ref} style={{ position: 'relative', width: 300 }}>
      <input
        value={value}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        style={{
          width: '100%',
          padding: 8,
          border: `2px solid ${isValid || value === '' ? '#ccc' : 'red'}`,
          borderRadius: 4,
        }}
      />
      {showDropdown && filtered.length > 0 && (
        <div
          style={{
            position: 'absolute',
            top: '100%',
            left: 0,
            right: 0,
            maxHeight: ITEM_HEIGHT * MAX_VISIBLE,
            border: '1px solid #ccc',
            background: '#fff',
            zIndex: 1000,
            overflow: 'auto',
          }}
        >
          <List
            height={Math.min(filtered.length, MAX_VISIBLE) * ITEM_HEIGHT}
            itemCount={filtered.length}
            itemSize={ITEM_HEIGHT}
            width={'100%'}
          >
            {({ index, style }) => (
              <div
                key={filtered[index]}
                style={{
                  ...style,
                  background: index === highlight ? '#e6f7ff' : '#fff',
                  padding: '8px 12px',
                  cursor: 'pointer',
                }}
                onMouseDown={e => e.preventDefault()}
                onClick={() => handleOptionClick(filtered[index])}
                onMouseEnter={() => setHighlight(index)}
              >
                {filtered[index]}
              </div>
            )}
          </List>
        </div>
      )}
    </div>
  );
};
```

