## My Own Answer

### Step 1: Enable Flakes

Edit `/etc/nix/nix.conf` and add:

```
experimental-features = nix-command flakes
```

### Step 2: Prepare Flake Directory

Choose a directory for your flake, e.g., `/etc/nixos/flake`:

```sh
sudo mkdir -p /etc/nixos/flake
cd /etc/nixos/flake
```

### Step 3: Create `flake.nix`

```nix
{
  description = "NixOS config with flakes and Home Manager";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    home-manager.url = "github:nix-community/home-manager";
    flake-utils.url = "github:numtide/flake-utils";
  };

  outputs = { self, nixpkgs, home-manager, flake-utils, ... }:
    flake-utils.lib.eachDefaultSystem (system:
      let
        pkgs = import nixpkgs {
          inherit system;
          config.allowUnfree = true;
        };
      in {
        nixosConfigurations = {
          my-host = pkgs.lib.nixosSystem {
            system = system;
            modules = [
              ./configuration.nix
              home-manager.nixosModules.home-manager
              {
                home-manager.useGlobalPkgs = true;
                home-manager.useUserPackages = true;
                home-manager.users.myuser = import ./home.nix;
              }
            ];
          };
        };
      }
    );
}
```

### Step 4: Create `configuration.nix`

```nix
{ config, pkgs, ... }:

{
  networking.hostName = "my-host";
  time.timeZone = "UTC";
  i18n.defaultLocale = "en_US.UTF-8";

  users.users.myuser = {
    isNormalUser = true;
    extraGroups = [ "wheel" "networkmanager" ];
    shell = pkgs.zsh;
  };

  services.xserver.enable = true;
  services.xserver.displayManager.gdm.enable = true;
  services.xserver.desktopManager.gnome.enable = true;
  services.xserver.displayManager.gdm.wayland = true;
  services.xserver.layout = "us";
  services.xserver.xkbOptions = "eurosign:e";
  services.xserver.wayland.enable = true;

  services.networkmanager.enable = true;

  environment.systemPackages = with pkgs; [
    curl wget git htop tmux unzip zip tree gcc gdb make
    neovim
    vscode
    brave
    bitwarden
    # zed may not be in nixpkgs; see below
  ];

  system.stateVersion = "23.11";
}
```

### Step 5: Create `home.nix`

```nix
{ config, pkgs, ... }:

{
  home.username = "myuser";
  home.homeDirectory = "/home/myuser";

  programs.neovim.enable = true;
  programs.zsh.enable = true;
  programs.git.enable = true;

  home.packages = with pkgs; [
    # If zed is not in nixpkgs, fetch it manually:
    (pkgs.stdenv.mkDerivation {
      pname = "zed";
      version = "0.121.0";
      src = pkgs.fetchurl {
        url = "https://github.com/zed-industries/zed/releases/download/v0.121.0/zed-x86_64-unknown-linux-gnu.tar.gz";
        sha256 = "sha256-...";
      };
      installPhase = ''
        mkdir -p $out/bin
        tar -xzf $src -C $out/bin --strip-components=1
      '';
    })
  ];
}
```

### Step 6: Build and Switch

```sh
sudo nixos-rebuild switch --flake /etc/nixos/flake#my-host
```

### Step 7: Login and Enjoy

Log in as `myuser`, start GNOME (should be default), and verify all tools are present.

