  i18n.defaultLocale = "en_US.UTF-8";

  users.users.alice = { # change to your username
    isNormalUser = true;
    extraGroups = [ "wheel" "networkmanager" ];
    shell = pkgs.zsh;
  };

  services.xserver.enable = true;
  services.xserver.displayManager.gdm.enable = true;
  services.xserver.displayManager.gdm.wayland = true;
  services.xserver.desktopManager.gnome.enable = true;

  services.networkmanager.enable = true;

  environment.systemPackages = with pkgs; [
    curl git htop wget unzip tree tmux gcc make gdb
    neovim
    vscode
    brave
    bitwarden
    zed # If not available, see below
  ];

  system.stateVersion = "23.11"; # adjust to your NixOS version
}
```

**Note:** If `zed` is not in nixpkgs, you may need to add it via overlay or manual derivation.

---

### Step 5: Create `home.nix`

Create `/etc/nixos/home.nix`:

```nix
{ config, pkgs, ... }:

{
  home.username = "alice";
  home.homeDirectory = "/home/alice";

  programs.neovim.enable = true;
  programs.zsh.enable = true;
  programs.git.enable = true;

  # Add per-user packages if desired
  home.packages = with pkgs; [
    # e.g., nodejs
  ];

  # Optionally, configure VS Code extensions, neovim plugins, etc.
}
```

---

### Step 6: Apply the Configuration

```bash
sudo nixos-rebuild switch --flake /etc/nixos#nixos
```

---

### Step 7: Post-Install

- Log in as your user.
- You should have GNOME on Wayland, all requested apps, and tools.
- If `zed` is not available, you can add it via a custom derivation or overlay.

---

