To add a restart button to this Arduino code, you need to:

1. Choose a digital pin for the button (e.g., pin 2 or 7).
2. Connect one leg of the button to the chosen digital pin, and the other leg to GND (minus).
3. In code, set the pin as `INPUT_PULLUP` in `setup()`.
4. In `loop()`, check if the button is pressed (the pin reads LOW), and if so, reset the game state (ball and paddles positions, directions, etc.), clear and redraw the display, and reset timers.

**Example code changes:**

```cpp
#define RESTART_BUTTON_PIN 2 // or any other digital pin

void setup() {
  pinMode(RESTART_BUTTON_PIN, INPUT_PULLUP);
  // ... rest of your setup code
}

void restartGame() {
  ball_x = 64;
  ball_y = 16;
  ball_dir_x = 1;
  ball_dir_y = 1;
  cpu_y = 8;
  player_y = 8;
  display.clearDisplay();
  drawCourt();
  display.fillRect(ball_x, ball_y, BALL_SIZE, BALL_SIZE, WHITE);
  display.drawFastVLine(CPU_X, cpu_y, PADDLE_HEIGHT, WHITE);
  display.drawFastVLine(PLAYER_X, player_y, PADDLE_HEIGHT, WHITE);
  display.display();
  ball_update = millis();
  paddle_update = millis();
}

void loop() {
  if (digitalRead(RESTART_BUTTON_PIN) == LOW) {
    delay(50); // debounce
    if (digitalRead(RESTART_BUTTON_PIN) == LOW) {
      restartGame();
      while (digitalRead(RESTART_BUTTON_PIN) == LOW) delay(10); // wait for release
    }
  }
  // ... rest of your loop code
}
