// Function to generate linearly spaced values (like np.linspace)
std::vector<double> linspace(double start, double end, int num) {
    std::vector<double> result(num);
    if (num == 1) {
        result[0] = start;
    } else {
        double step = (end - start) / (num - 1);
        for (int i = 0; i < num; ++i) {
            result[i] = start + i * step;
        }
    }
    return result;
