// Linear interpolation function
double interp1d(const std::vector<double>& x, const std::vector<double>& y, double x_new) {
    int n = x.size();
    if (x_new <= x.front()) return y.front();
    if (x_new >= x.back()) return y.back();
    for (int i = 0; i < n - 1; ++i) {
        if (x_new >= x[i] && x_new <= x[i+1]) {
            double t = (x_new - x[i]) / (x[i+1] - x[i]);
            return y[i] + t * (y[i+1] - y[i]);
        }
    }
    return 0.0; // Should not reach here
}

