Here is a production-ready React Native component that implements expandable text functionality. It shows only one line of text by default, and if the text is longer than one line, it appends a "See more" link at the end. When "See more" is clicked, the full text is displayed.

```jsx
import React, { useState } from 'react';
import { Text, StyleSheet, View } from 'react-native';

const ExpandableText = ({
  text,
  seeMoreText = 'See more',
  textStyle,
  seeMoreStyle,
  containerStyle,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [showSeeMore, setShowSeeMore] = useState(false);

  const onTextLayout = (e) => {
    if (e.nativeEvent.lines.length > 1 && !isExpanded) {
      setShowSeeMore(true);
    }
  };

  return (
    <View style={containerStyle}>
      <Text
        style={textStyle}
        numberOfLines={isExpanded ? undefined : 1}
        onTextLayout={onTextLayout}
      >
        {text}
        {!isExpanded && showSeeMore && (
          <Text
            style={[styles.seeMore, seeMoreStyle]}
            onPress={() => setIsExpanded(true)}
          >
            {' '} {seeMoreText}
          </Text>
        )}
      </Text>
    </View>
  );
};

const styles = StyleSheet.create({
  seeMore: {
    color: '#007AFF',
    fontWeight: 'bold',
  },
});

export default ExpandableText;
```

**Usage Example:**

```jsx
