    @Id
    private Integer id;
    // ... other fields and getters/setters
}

@Entity
@Table(name = "user_account")
public class UserAccount implements Account {
    @Id
    private Integer id;
    // ... other fields and getters/setters
}
```

3. **Define a strategy interface:**
```java
public interface AccountRetrievalStrategy {
    Account getById(Integer id);
    boolean supports(String accountType); // or use an enum
}
```

4. **Implement a strategy for each account type:**
```java
@Service
public class DoctorAccountRetrievalStrategy implements AccountRetrievalStrategy {
    @Autowired
    private DoctorAccountRepository repo;

    @Override
    public Account getById(Integer id) {
        return repo.findById(id).orElse(null);
    }

    @Override
    public boolean supports(String accountType) {
        return "doctor".equalsIgnoreCase(accountType);
    }
}

@Service
public class UserAccountRetrievalStrategy implements AccountRetrievalStrategy {
    @Autowired
    private UserAccountRepository repo;

    @Override
    public Account getById(Integer id) {
        return repo.findById(id).orElse(null);
    }

    @Override
    public boolean supports(String accountType) {
        return "user".equalsIgnoreCase(accountType);
    }
}
```

5. **Create a factory/registry to select the correct strategy:**
```java
@Component
public class AccountStrategyFactory {
    private final List<AccountRetrievalStrategy> strategies;

    @Autowired
    public AccountStrategyFactory(List<AccountRetrievalStrategy> strategies) {
        this.strategies = strategies;
    }

    public AccountRetrievalStrategy getStrategy(String accountType) {
        return strategies.stream()
            .filter(s -> s.supports(accountType))
            .findFirst()
            .orElseThrow(() -> new IllegalArgumentException("Unknown account type: " + accountType));
    }
}
```

6. **Service layer usage:**
```java
