    button, select { font-family:inherit; font-size:1em; padding:2px 8px; border-radius:3px; border:none; background:#444; color:#eee;}
    button:hover, select:hover { background:#666;}
    #editor-container { flex:1; display:flex; background:#181818;}
    #line-numbers { background:#222; color:#888; padding:8px 4px; text-align:right; min-width:36px; user-select:none;}
    #editor-wrapper { position:relative; flex:1; }
    #highlighting { position:absolute; top:0; left:0; width:100%; pointer-events:none; color:transparent; white-space:pre-wrap; word-break:break-word; z-index:0; padding:8px;}
    #editor { position:relative; width:100%; height:100%; background:transparent; color:inherit; border:none; outline:none; resize:none; font-family:inherit; font-size:1em; line-height:1.4; padding:8px; z-index:1;}
    .token.keyword { color:#d73a49;}
    .token.string { color:#a5e075;}
    .token.comment { color:#6a9955; font-style:italic;}
    .token.number { color:#b392f0;}
    .token.tag { color:#569cd6;}
    .token.attr { color:#9cdcfe;}
    .token.attr-value { color:#ce9178;}
    body.light { background:#f5f5f5; color:#222;}
    body.light header, body.light footer { background:#eee; color:#222;}
    body.light #editor-container { background:#fff;}
    body.light #line-numbers { background:#f0f0f0; color:#aaa;}
    #find-panel { display:none; background:#222; color:#eee; padding:8px;}
    body.light #find-panel { background:#eee; color:#222;}
    #find-panel input { font-family:inherit; font-size:1em; padding:2px 4px;}
    #find-panel button { font-size:0.9em;}
    #status { flex:1; text-align:right;}
  </style>
</head>
<body>
  <header>
    <div><b>Advanced Notepad</b></div>
    <div class="controls">
      <button id="new-btn">New</button>
      <button id="open-btn">Open</button>
      <button id="save-btn">Save</button>
      <select id="lang-select">
        <option value="plaintext">Plain Text</option>
        <option value="javascript" selected>JavaScript</option>
        <option value="html">HTML</option>
        <option value="css">CSS</option>
      </select>
      <button id="find-btn">Find/Replace</button>
      <button id="theme-btn">Toggle Theme</button>
      <label>Font Size: <input id="font-size" type="number" min="10" max="32" value="16" style="width:40px;"></label>
    </div>
  </header>
  <div id="find-panel">
    <input id="find-input" placeholder="Find">
    <input id="replace-input" placeholder="Replace">
    <button id="find-next-btn">Next</button>
    <button id="replace-btn">Replace</button>
    <button id="replace-all-btn">Replace All</button>
    <button id="close-find-btn">Close</button>
  </div>
  <div id="editor-container">
    <div id="line-numbers">1</div>
    <div id="editor-wrapper">
      <pre id="highlighting"></pre>
      <textarea id="editor" spellcheck="false"></textarea>
    </div>
  </div>
  <footer>
    <span id="status">Lines: 1 | Words: 0 | Chars: 0</span>
  </footer>
  <input type="file" id="file-input" style="display:none;">
  <script>
    const editor = document.getElementById('editor');
    const highlighting = document.getElementById('highlighting');
    const lineNumbers = document.getElementById('line-numbers');
    const status = document.getElementById('status');
    const langSelect = document.getElementById('lang-select');
    const fontSizeInput = document.getElementById('font-size');
    // Find/replace
    const findPanel = document.getElementById('find-panel');
    const findInput = document.getElementById('find-input');
    const replaceInput = document.getElementById('replace-input');
    let findIndex = 0, findMatches = [];
    // Load from localStorage
    if(localStorage.getItem('advnp-content')) editor.value = localStorage.getItem('advnp-content');
    updateAll();
    editor.addEventListener('input', ()=>{ updateAll(); localStorage.setItem('advnp-content', editor.value); });
    editor.addEventListener('scroll', ()=>{ highlighting.scrollTop = editor.scrollTop; lineNumbers.scrollTop = editor.scrollTop; });
    editor.addEventListener('keydown', e=>{
      if(e.key==='Tab'){ e.preventDefault();
        const s = editor.selectionStart, e2 = editor.selectionEnd;
        if(s!==e2){
          let val = editor.value, sel = val.slice(s,e2);
          let lines = sel.split('\n');
          let add = !lines.every(l=>l.startsWith('    '));
          lines = lines.map(l=>add?'    '+l:l.replace(/^ {1,4}/,''));
          let newSel = lines.join('\n');
          editor.value = val.slice(0,s)+newSel+val.slice(e2);
          editor.selectionStart = s; editor.selectionEnd = s+newSel.length;
        } else {
          let val = editor.value;
          editor.value = val.slice(0,s)+'    '+val.slice(s);
          editor.selectionStart = editor.selectionEnd = s+4;
        }
        updateAll();
      }
      if(e.key==='Enter'){
        let start = editor.selectionStart;
        let val = editor.value;
        let lineStart = val.lastIndexOf('\n', start-1)+1;
        let indent = (val.slice(lineStart,start).match(/^\s+/)||[''])[0];
        setTimeout(()=>{
          let pos = editor.selectionStart;
          editor.value = editor.value.slice(0,pos)+indent+editor.value.slice(pos);
          editor.selectionStart = editor.selectionEnd = pos+indent.length;
          updateAll();
        },0);
      }
      if((e.ctrlKey||e.metaKey)&&e.key==='s'){ e.preventDefault(); saveFile(); }
      if((e.ctrlKey||e.metaKey)&&e.key==='f'){ e.preventDefault(); showFindPanel(); }
    });
    document.getElementById('new-btn').onclick = ()=>{ if(confirm('New file?')){ editor.value=''; updateAll(); }};
    document.getElementById('open-btn').onclick = ()=>{ document.getElementById('file-input').click(); };
    document.getElementById('save-btn').onclick = saveFile;
    document.getElementById('theme-btn').onclick = ()=>{ document.body.classList.toggle('light'); };
    langSelect.onchange = updateAll;
    fontSizeInput.oninput = ()=>{ editor.style.fontSize=fontSizeInput.value+'px'; highlighting.style.fontSize=fontSizeInput.value+'px'; };
    document.getElementById('file-input').onchange = e=>{
      let file = e.target.files[0];
      if(file){
        let r = new FileReader();
        r.onload = ev=>{ editor.value=ev.target.result; updateAll(); };
        r.readAsText(file);
      }
    };
    // Find/replace
    document.getElementById('find-btn').onclick = showFindPanel;
    document.getElementById('close-find-btn').onclick = ()=>{ findPanel.style.display='none'; };
    document.getElementById('find-next-btn').onclick = findNext;
    document.getElementById('replace-btn').onclick = replaceOne;
    document.getElementById('replace-all-btn').onclick = replaceAll;
    function showFindPanel(){ findPanel.style.display='block'; findInput.focus(); findMatches=[]; findIndex=0; }
    function findNext(){
      let txt = findInput.value;
      if(!txt) return;
      let val = editor.value;
      let idx = val.indexOf(txt, editor.selectionEnd);
      if(idx===-1) idx = val.indexOf(txt,0);
      if(idx!==-1){
        editor.focus();
        editor.selectionStart=idx;
        editor.selectionEnd=idx+txt.length;
      }
    }
    function replaceOne(){
      let txt = findInput.value, rep = replaceInput.value;
      if(!txt) return;
      let s = editor.selectionStart, e = editor.selectionEnd;
      if(editor.value.slice(s,e)===txt){
        editor.value = editor.value.slice(0,s)+rep+editor.value.slice(e);
        editor.selectionStart = editor.selectionEnd = s+rep.length;
        updateAll();
      }
      findNext();
    }
    function replaceAll(){
      let txt = findInput.value, rep = replaceInput.value;
      if(!txt) return;
      editor.value = editor.value.split(txt).join(rep);
      updateAll();
    }
    function saveFile(){
      let blob = new Blob([editor.value],{type:'text/plain'});
      let a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'note.txt';
      a.click();
      URL.revokeObjectURL(a.href);
    }
    function updateAll(){
      updateHighlight();
      updateLineNumbers();
      updateStatus();
    }
    function updateHighlight(){
      let code = editor.value.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
      let lang = langSelect.value;
      if(lang==='javascript'){
        code = code.replace(/(\/\/.*|\/\*[\s\S]*?\*\/)/g,'<span class="token comment">$1</span>');
        code = code.replace(/(["'`])(?:\\.|(?!\1).)*\1/g,'<span class="token string">$&</span>');
        code = code.replace(/\b(var|let|const|if|else|for|while|function|return|class|try|catch|finally|throw|await|async|new|this|typeof|instanceof|switch|case|break|default|import|from|export|extends|super|in|of)\b/g,'<span class="token keyword">$1</span>');
        code = code.replace(/\b\d+(\.\d+)?\b/g,'<span class="token number">$&</span>');
      } else if(lang==='html'){
        code = code.replace(/(&lt;!--[\s\S]*?--&gt;)/g,'<span class="token comment">$1</span>');
        code = code.replace(/(&lt;\/?[a-zA-Z]+)([^&]*?)(&gt;)/g, function(m,p1,p2,p3){
          p2 = p2.replace(/([a-zA-Z-:]+)(=)("[^"]*"|'[^']*')/g,'<span class="token attr">$1</span>$2<span class="token attr-value">$3</span>');
          return '<span class="token tag">'+p1+'</span>'+p2+'<span class="token tag">'+p3+'</span>';
        });
      } else if(lang==='css'){
        code = code.replace(/(\/\*[\s\S]*?\*\/)/g,'<span class="token comment">$1</span>');
        code = code.replace(/([.#]?[a-zA-Z0-9_-]+)(\s*\{)/g,'<span class="token keyword">$1</span>$2');
        code = code.replace(/(["'`])(?:\\.|(?!\1).)*\1/g,'<span class="token string">$&</span>');
        code = code.replace(/\b\d+(\.\d+)?(px|em|rem|%)?\b/g,'<span class="token number">$&</span>');
      }
      highlighting.innerHTML = code;
    }
