  <div id="status">
    <span id="stat1">Ln 1, Col 1</span>
    <span id="stat2">Words: 0 | Chars: 0</span>
  </div>
  <script>
    // Elements
    const editor = document.getElementById('editor');
    const highlight = document.getElementById('highlight');
    const lines = document.getElementById('lines');
    const langSel = document.getElementById('langSel');
    const fontSize = document.getElementById('fontSize');
    const themeBtn = document.getElementById('themeBtn');
    const status1 = document.getElementById('stat1');
    const status2 = document.getElementById('stat2');
    const openBtn = document.getElementById('openBtn');
    const saveBtn = document.getElementById('saveBtn');
    const undoBtn = document.getElementById('undoBtn');
    const redoBtn = document.getElementById('redoBtn');
    const fileInput = document.getElementById('fileInput');
    const findBtn = document.getElementById('findBtn');
    const findPanel = document.getElementById('findPanel');
    const findText = document.getElementById('findText');
    const replaceText = document.getElementById('replaceText');
    const regexChk = document.getElementById('regexChk');
    const findNextBtn = document.getElementById('findNextBtn');
    const replaceBtn = document.getElementById('replaceBtn');
    const replaceAllBtn = document.getElementById('replaceAllBtn');
    const closeFindBtn = document.getElementById('closeFindBtn');

    // State
    let undoStack = [], redoStack = [];
    let findMatches = [], findIdx = -1;

    // Syntax highlighting
    function escapeHtml(s) {
      return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
    }
    function highlightCode(code, lang) {
      code = escapeHtml(code);
      if(lang === 'js') {
        code = code.replace(/(\/\/.*|\/\*[\s\S]*?\*\/)/g, '<span class="token comment">$1</span>');
        code = code.replace(/(["'`])(?:\\.|(?!\1).)*\1/g, '<span class="token string">$&</span>');
        code = code.replace(/\b(function|return|var|let|const|if|else|for|while|break|continue|switch|case|default|throw|try|catch|finally|new|this|typeof|instanceof|in|of|do|await|async|class|extends|super|import|from|export)\b/g, '<span class="token keyword">$1</span>');
        code = code.replace(/\b\d+(\.\d+)?\b/g, '<span class="token number">$&</span>');
      } else if(lang === 'html') {
        code = code.replace(/(&lt;!--[\s\S]*?--&gt;)/g, '<span class="token comment">$1</span>');
        code = code.replace(/(&lt;\/?[a-zA-Z0-9\-]+)([^&]*?)(&gt;)/g, function(m,p1,p2,p3){
          p2 = p2.replace(/([a-zA-Z\-:]+)(=)("[^"]*"|'[^']*')/g, '<span class="token attr">$1</span>$2<span class="token attr-value">$3</span>');
          return '<span class="token tag">'+p1+'</span>'+p2+'<span class="token tag">'+p3+'</span>';
        });
      } else if(lang === 'css') {
        code = code.replace(/(\/\*[\s\S]*?\*\/)/g, '<span class="token comment">$1</span>');
        code = code.replace(/([.#]?[a-zA-Z0-9_-]+)(\s*\{)/g, '<span class="token selector">$1</span>$2');
        code = code.replace(/([a-zA-Z-]+)(:)/g, '<span class="token property">$1</span>$2');
        code = code.replace(/("([^"\\]|\\.)*")|('([^'\\]|\\.)*')/g, '<span class="token string">$&</span>');
        code = code.replace(/\b\d+(\.\d+)?(px|em|rem|%)?\b/g, '<span class="token number">$&</span>');
      }
      // Find highlight
      if(findMatches.length && findText.value) {
        let idx = 0;
        code = code.replace(new RegExp(escapeRegExp(findText.value), 'g'), m => {
          let mark = `<mark class="findmark"${idx===findIdx?' style="background:orange;"':''}>${m}</mark>`;
          idx++;
          return mark;
        });
      }
      return code;
    }
    function escapeRegExp(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

    // Update all
    function update() {
      // Highlight
      highlight.innerHTML = highlightCode(editor.value, langSel.value);
      // Lines
      lines.innerHTML = Array(editor.value.split('\n').length).fill(0).map((_,i)=>i+1).join('<br>');
      // Status
      let pos = editor.selectionStart;
      let before = editor.value.slice(0,pos);
      let line = before.split('\n').length;
      let col = before.length - before.lastIndexOf('\n');
      status1.textContent = `Ln ${line}, Col ${col}`;
      let words = (editor.value.match(/\b\w+\b/g)||[]).length;
      status2.textContent = `Words: ${words} | Chars: ${editor.value.length}`;
      // Save
      localStorage.setItem('advnpad', JSON.stringify({
        content: editor.value,
        lang: langSel.value,
        theme: document.body.classList.contains('light'),
        font: fontSize.value
      }));
    }
    // Undo/redo
    function pushUndo() {
      if(undoStack.length>100) undoStack.shift();
      undoStack.push(editor.value);
      redoStack = [];
    }
    function undo() {
      if(undoStack.length>1) {
        redoStack.push(undoStack.pop());
        editor.value = undoStack[undoStack.length-1];
        update();
      }
    }
    function redo() {
      if(redoStack.length) {
        let v = redoStack.pop();
        undoStack.push(v);
        editor.value = v;
        update();
      }
    }
    // Auto indent
    editor.addEventListener('keydown', e=>{
      if(e.key==='Tab') {
        e.preventDefault();
        let s = editor.selectionStart, e2 = editor.selectionEnd;
        editor.setRangeText('  ', s, e2, 'end');
        update();
        pushUndo();
      } else if(e.key==='Enter') {
        let val = editor.value, pos = editor.selectionStart;
        let lineStart = val.lastIndexOf('\n', pos-1)+1;
        let indent = (val.slice(lineStart,pos).match(/^\s+/)||[''])[0];
        setTimeout(()=>{
          editor.setRangeText(indent, editor.selectionStart, editor.selectionStart, 'end');
          update();
        },0);
      } else if((e.ctrlKey||e.metaKey)&&e.key==='z') { e.preventDefault(); undo();}
      else if((e.ctrlKey||e.metaKey)&&e.key==='y') { e.preventDefault(); redo();}
      else if((e.ctrlKey||e.metaKey)&&e.key==='s') { e.preventDefault(); saveFile();}
      else if((e.ctrlKey||e.metaKey)&&e.key==='f') { e.preventDefault(); showFind();}
    });
    editor.addEventListener('input', ()=>{ update(); pushUndo(); });
    editor.addEventListener('scroll', ()=>{
      highlight.scrollTop = editor.scrollTop;
      lines.scrollTop = editor.scrollTop;
    });
    editor.addEventListener('click', update);
    editor.addEventListener('keyup', update);

    // Font size
    fontSize.addEventListener('input', ()=>{
      editor.style.fontSize = fontSize.value+'px';
      highlight.style.fontSize = fontSize.value+'px';
      update();
    });

    // Theme
    themeBtn.addEventListener('click', ()=>{
      document.body.classList.toggle('light');
      update();
    });

    // Lang
    langSel.addEventListener('change', update);

    // File open/save
    openBtn.addEventListener('click', ()=>fileInput.click());
    fileInput.addEventListener('change', e=>{
      let f = fileInput.files[0];
      if(f) {
        let r = new FileReader();
        r.onload = e=>{ editor.value = e.target.result; update(); pushUndo(); };
        r.readAsText(f);
      }
    });
    function saveFile() {
      let blob = new Blob([editor.value], {type:'text/plain'});
      let a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'note.'+langSel.value;
      a.click();
      URL.revokeObjectURL(a.href);
    }
    saveBtn.addEventListener('click', saveFile);

    // Undo/redo
    undoBtn.addEventListener('click', undo);
    redoBtn.addEventListener('click', redo);

    // Find/replace
    function showFind() { findPanel.style.display='block'; findText.focus(); }
    function hideFind() { findPanel.style.display='none'; }
    findBtn.addEventListener('click', showFind);
    closeFindBtn.addEventListener('click', hideFind);

    function doFindAll() {
      findMatches = [];
      findIdx = -1;
      if(!findText.value) return;
      let re = regexChk.checked ? new RegExp(findText.value,'g') : new RegExp(escapeRegExp(findText.value),'g');
      let m, text = editor.value;
      while((m=re.exec(text))!==null) {
        findMatches.push({start:m.index, end:m.index+m[0].length});
        if(m.index===re.lastIndex) re.lastIndex++;
      }
      if(findMatches.length) findIdx = 0;
    }
    function selectFind() {
      if(findIdx<0||!findMatches.length) return;
      let m = findMatches[findIdx];
      editor.focus();
      editor.selectionStart = m.start;
      editor.selectionEnd = m.end;
      update();
    }
    findText.addEventListener('input', ()=>{ doFindAll(); selectFind(); });
    findNextBtn.addEventListener('click', ()=>{
      if(!findMatches.length) return;
      findIdx = (findIdx+1)%findMatches.length;
      selectFind();
    });
    replaceBtn.addEventListener('click', ()=>{
      if(findIdx<0||!findMatches.length) return;
      let m = findMatches[findIdx];
      let val = editor.value;
      editor.value = val.slice(0,m.start)+replaceText.value+val.slice(m.end);
      update();
      doFindAll();
      selectFind();
    });
    replaceAllBtn.addEventListener('click', ()=>{
      if(!findText.value) return;
      let re = regexChk.checked ? new RegExp(findText.value,'g') : new RegExp(escapeRegExp(findText.value),'g');
      editor.value = editor.value.replace(re, replaceText.value);
      update();
      doFindAll();
    });

    // Load state
    window.addEventListener('DOMContentLoaded', ()=>{
      let s = localStorage.getItem('advnpad');
      if(s) {
        try {
          let o = JSON.parse(s);
          editor.value = o.content||'';
          langSel.value = o.lang||'js';
          if(o.theme) document.body.classList.add('light');
          fontSize.value = o.font||16;
          editor.style.fontSize = fontSize.value+'px';
          highlight.style.fontSize = fontSize.value+'px';
        } catch(e){}
      }
      update();
      pushUndo();
    });
  </script>
</body>
</html>
