import SwiftUI

struct EqualizerView: View {
    var audioPower: Float
    var isRecording: Bool
    let barCount = 5

    func normalizedPower(_ power: Float) -> CGFloat {
        let minDb: Float = -60
        let clamped = max(power, minDb)
        return CGFloat((clamped - minDb) / -minDb)
    }

    var body: some View {
        HStack(spacing: 6) {
            ForEach(0..<barCount, id: \.self) { _ in
                let height = isRecording ? normalizedPower(audioPower) * CGFloat.random(in: 0.5...1.0) * 100 : 10
                RoundedRectangle(cornerRadius: 3)
                    .fill(Color.blue)
                    .frame(width: 10, height: height)
                    .animation(.easeInOut(duration: 0.1), value: height)
            }
        }
        .frame(height: 100)
    }
}
```

