    bool ok = false;
    // Hexadecimal: 0x...
    if (s.startsWith("0x")) {
        result = s.mid(2).toInt(&ok, 16);
        return ok;
    }
    // Binary: 0b...
    if (s.startsWith("0b")) {
        result = s.mid(2).toInt(&ok, 2);
        return ok;
    }
    // Octal: starts with 0, more than one digit, not 0x/0b
    if (s.startsWith('0') && s.length() > 1 && !s.startsWith("0x") && !s.startsWith("0b")) {
        result = s.toInt(&ok, 8);
        return ok;
