Let's start by generating my own answer to the prompt.

---

**My Answer:**

This is a classic minimum spanning tree (MST) problem with a twist: the cost to build a road between two houses is the sum of their prices, and some roads already exist. We need to ensure the city is fully connected at minimal cost.

**Approach:**

1. **Model the city as a graph:** Houses are nodes, roads are edges.
2. **Find connected components:** Use Union-Find (DSU) to process the existing roads and identify connected components.
3. **For each component, find the house with the minimal price.**
4. **Connect all components:** To minimize cost, connect all components to the component containing the globally cheapest house. For each other component, connect its cheapest house to the globally cheapest house.
5. **Output:** The number of new roads and the list of roads to build.

**Implementation (C++):**

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) : parent(n+1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        parent[find(x)] = find(y);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n+1);
    for (int i = 1; i <= n; ++i) cin >> a[i];

    DSU dsu(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        dsu.unite(u, v);
    }

    // Find cheapest house in each component
    unordered_map<int, pair<long long, int>> comp_min;
    for (int i = 1; i <= n; ++i) {
        int p = dsu.find(i);
        if (!comp_min.count(p) || a[i] < comp_min[p].first)
            comp_min[p] = {a[i], i};
    }

    // Find the globally cheapest house
    int global = -1;
    long long min_price = LLONG_MAX;
    for (auto& [p, pr] : comp_min) {
        if (pr.first < min_price) {
            min_price = pr.first;
            global = pr.second;
        }
    }

    // Connect all other components to the global cheapest house
    vector<pair<int, int>> roads;
    for (auto& [p, pr] : comp_min) {
        if (pr.second != global)
            roads.emplace_back(global, pr.second);
    }

    cout << roads.size() << "\n";
    for (auto& [u, v] : roads)
        cout << u << " " << v << "\n";
    return 0;
}
```

**Explanation:**
- We use DSU to find components.
- For each component, we find its cheapest house.
- We connect all components to the one with the globally cheapest house, minimizing the total cost.

---

