Let's start by generating my own answer to the prompt.

---

**My Answer:**

This is a classic minimum spanning tree (MST) problem with a twist: some edges (roads) already exist, and the cost to build a new road between two houses is the sum of their prices.

**Approach:**

1. **Model the Problem:**  
   - Each house is a node.
   - Each existing road is an edge (cost 0, since already built).
   - The cost to build a new road between house i and j is a[i] + a[j].

2. **Find Connected Components:**  
   - Use Union-Find (Disjoint Set Union, DSU) to find all connected components based on the existing roads.

3. **Connect Components Minimally:**  
   - To connect all components with minimal cost, connect the cheapest house in each component to the cheapest house in the entire city (or, equivalently, connect all components in a "star" centered at the global minimum).
   - For k components, you need k-1 new roads.

4. **Implementation Steps:**  
   - Read input, build DSU with existing roads.
   - For each component, find its cheapest house.
   - Find the global cheapest house.
   - For each component (except the one containing the global minimum), connect its cheapest house to the global minimum.
   - Output the number of new roads and the list of roads.

**C++ Code:**

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) : parent(n) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x != y) parent[y] = x;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    DSU dsu(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        dsu.unite(u, v);
    }

    // Find cheapest house in each component
    vector<int> min_in_comp(n, -1);
    for (int i = 0; i < n; ++i) {
        int p = dsu.find(i);
        if (min_in_comp[p] == -1 || a[i] < a[min_in_comp[p]])
            min_in_comp[p] = i;
    }

    // Find global minimum
    int global_min = min_in_comp[0];
    for (int i = 1; i < n; ++i) {
        if (min_in_comp[i] != -1 && a[min_in_comp[i]] < a[global_min])
            global_min = min_in_comp[i];
    }

    // Connect all other components to the global minimum
    vector<pair<int, int>> roads;
    int root = dsu.find(global_min);
    for (int i = 0; i < n; ++i) {
        if (min_in_comp[i] != -1 && dsu.find(min_in_comp[i]) != root) {
            roads.emplace_back(global_min + 1, min_in_comp[i] + 1);
            dsu.unite(global_min, min_in_comp[i]);
        }
    }

    cout << roads.size() << "\n";
    for (auto &r : roads) cout << r.first << " " << r.second << "\n";
    return 0;
}
```

**Explanation:**  
- The code finds all connected components, then connects each component's cheapest house to the global cheapest house, ensuring minimal total cost and full connectivity.

