              mountPath: "/config"
            }]
          },
          #Container & {
            name:  "nginx"
            image: "nginx:latest"
            ports: [{
              containerPort: 80
              name:        "nginx-web"
            }]
            volumeMounts: [{
              name:      "nginx-config"
              mountPath: "/etc/nginx/conf.d"
            }]
          },
