- Calculate simulated time
- Determine current event
- Set outputs (LEDs) accordingly
- Update OLED display

**10. Example Code Skeleton:**
```cpp
#include <Wire.h>
#include <RTClib.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define OLED_ADDR 0x3C
Adafruit_SSD1306 display(128, 64, &Wire, -1);
RTC_DS3231 rtc;

const int livingRoomTVPin = 2;
const int bedroomTVPin = 3;
const int nightModePin = 6; // Button

unsigned long simStartMillis;
unsigned long simStartTime = 6 * 3600; // Start at 6:00
unsigned long SIM_FACTOR = 6;

void setup() {
  pinMode(livingRoomTVPin, OUTPUT);
  pinMode(bedroomTVPin, OUTPUT);
  pinMode(nightModePin, INPUT_PULLUP);
  Wire.begin();
  rtc.begin();
  display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR);
  simStartMillis = millis();
}

bool flicker() {
  return random(0, 100) < 80;
}

void loop() {
  unsigned long realElapsed = millis() - simStartMillis;
  unsigned long simElapsed = (realElapsed / 1000UL) * SIM_FACTOR;
  unsigned long simTime = (simStartTime + simElapsed) % 86400;
  int hour = simTime / 3600;
  int min = (simTime % 3600) / 60;

  bool nightMode = digitalRead(nightModePin) == HIGH;
  unsigned long nightDuration = nightMode ? 2 * 3600 : 1 * 3600;

  // Event logic
  bool livingRoomTV = false, bedroomTV = false;
  String event = "None";
  if (simTime >= 6*3600 && simTime < 7*3600) {
    bedroomTV = flicker();
    event = "Morning News";
  } else if (simTime >= 19*3600 && simTime < 20*3600) {
    livingRoomTV = flicker();
    event = "Evening TV";
  } else if (simTime >= 22*3600 && simTime < 22*3600 + nightDuration) {
    bedroomTV = flicker();
    event = "Bedtime TV";
  }

  digitalWrite(livingRoomTVPin, livingRoomTV);
  digitalWrite(bedroomTVPin, bedroomTV);

  // OLED update
  display.clearDisplay();
  display.setTextSize(2);
  display.setCursor(0,0);
  display.print(hour); display.print(":");
  if (min < 10) display.print("0");
  display.print(min);
  display.setTextSize(1);
  display.setCursor(0, 30);
  display.print(event);
  display.display();

  delay(100);
}
```
