        { id: 'fullName', help: 'helpFullName' },
        { id: 'email', help: 'helpEmail' },
        { id: 'password', help: 'helpPassword' }
    ];
    let step = 0;

    function setStep(idx) {
        fields.forEach((f, i) => {
            const input = document.getElementById(f.id);
            input.disabled = i !== idx;
            input.classList.toggle('active-field', i === idx);
        });
        document.getElementById(fields[idx].id).focus();
        document.getElementById('nextBtn').style.display = idx < fields.length - 1 ? '' : 'none';
        document.getElementById('submitBtn').style.display = idx === fields.length - 1 ? '' : 'none';
