            <div class="info" id="info-email" style="display:none;">Enter a valid email address.</div>
        </div>
        <div>
            <label>Password</label>
            <input id="password" type="password" disabled />
            <div class="info" id="info-password" style="display:none;">Password must be at least 6 characters.</div>
        </div>
        <button type="button" id="nextBtn">Next</button>
        <button type="submit" id="submitBtn" style="display:none;">Submit</button>
    </form>
