        const steps = [
            { id: 'username', info: 'info-username', validate: v => v.length >= 3 },
            { id: 'email', info: 'info-email', validate: v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) },
            { id: 'password', info: 'info-password', validate: v => v.length >= 6 }
        ];
        let current = 0;

        function showStep(idx) {
            steps.forEach((step, i) => {
                const input = document.getElementById(step.id);
                const info = document.getElementById(step.info);
                if (i === idx) {
                    input.disabled = false;
                    input.classList.add('active');
                    info.style.display = 'block';
                    input.focus();
                } else {
                    input.disabled = true;
                    input.classList.remove('active');
                    info.style.display = 'none';
                }
            });
            document.getElementById('nextBtn').style.display = idx < steps.length - 1 ? 'inline' : 'none';
            document.getElementById('submitBtn').style.display = idx === steps.length - 1 ? 'inline' : 'none';
        }

        document.getElementById('nextBtn').onclick = function() {
            const step = steps[current];
            const value = document.getElementById(step.id).value.trim();
            if (!step.validate(value)) {
                alert('Please enter valid input.');
                return;
            }
            if (current < steps.length - 1) {
                current++;
                showStep(current);
            }
        };

        document.getElementById('regForm').onsubmit = async function(e) {
            e.preventDefault();
            const step = steps[current];
            const value = document.getElementById(step.id).value.trim();
            if (!step.validate(value)) {
                alert('Please enter valid input.');
                return;
            }
            // Gather data
            const data = {};
            steps.forEach(s => data[s.id] = document.getElementById(s.id).value.trim());
            // Submit via fetch
            const res = await fetch('/api/registration', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(data)
            });
            const msg = await res.text();
            document.getElementById('result').innerText = msg;
        };

        // Initialize
        showStep(0);
    </script>
</body>
