To create an infinite scrolling table in Vue 3 with Pinia and JavaScript, where rows are fetched from a REST API using `start` and `count` parameters, and the table header remains fixed, follow these steps:

**1. Pinia Store (`stores/rows.js`):**

```js
import { defineStore } from 'pinia';

export const useRowsStore = defineStore('rows', {
  state: () => ({
    rows: [],
    loading: false,
    hasMore: true,
  }),
  actions: {
    async fetchRows(start, count) {
      if (this.loading || !this.hasMore) return;
      this.loading = true;
      try {
        const res = await fetch(`/api/rows?start=${start}&count=${count}`);
        const data = await res.json();
        if (data.rows.length < count) this.hasMore = false;
        this.rows.push(...data.rows);
      } catch (e) {
        console.error(e);
      } finally {
        this.loading = false;
      }
    },
    reset() {
      this.rows = [];
      this.hasMore = true;
      this.loading = false;
    }
  }
});
```

**2. Infinite Scrolling Table Component (`components/InfiniteScrollTable.vue`):**

```vue
<template>
  <div class="table-container" ref="container" @scroll="onScroll">
    <table>
      <thead>
        <tr>
          <th>ID</th>
          <th>Name</th>
          <th>Email</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="row in rowsStore.rows" :key="row.id">
          <td>{{ row.id }}</td>
          <td>{{ row.name }}</td>
          <td>{{ row.email }}</td>
        </tr>
        <tr v-if="rowsStore.loading">
          <td colspan="3">Loading...</td>
        </tr>
      </tbody>
    </table>
  </div>
</template>

<script>
import { ref, onMounted } from 'vue';
import { useRowsStore } from '../stores/rows';

export default {
  setup() {
    const rowsStore = useRowsStore();
    const container = ref(null);
    const BATCH_SIZE = 20;

    const onScroll = () => {
      const el = container.value;
      if (!el) return;
      if (el.scrollTop + el.clientHeight >= el.scrollHeight - 100) {
        rowsStore.fetchRows(rowsStore.rows.length, BATCH_SIZE);
      }
    };

    onMounted(() => {
      rowsStore.reset();
      rowsStore.fetchRows(0, BATCH_SIZE);
    });

    return { rowsStore, container, onScroll };
  }
};
</script>

