Here is a correct and clear implementation in C, closely following the described steps:

```c
#include <stdio.h>

// Extended Euclidean Algorithm
// Returns gcd(a, b), and finds x, y such that a*x + b*y = gcd(a, b)
void extendedEuclid(int a, int b, int *d, int *x, int *y) {
    int X2 = 1, X1 = 0;
    int Y2 = 0, Y1 = 1;
    int q, r, X, Y;

    if (b == 0) {
        *d = a;
        *x = 1;
        *y = 0;
        return;
    }

    while (b > 0) {
        q = a / b;
        r = a - q * b;
        X = X2 - q * X1;
        Y = Y2 - q * Y1;

        a = b;
        b = r;
        X2 = X1;
        X1 = X;
        Y2 = Y1;
        Y1 = Y;
    }

    *d = a;
    *x = X2;
    *y = Y2;
}

int main() {
    int a, b, d, x, y;
    printf("Nhap a va b: ");
    scanf("%d %d", &a, &b);

    extendedEuclid(a, b, &d, &x, &y);

    printf("gcd(%d, %d) = %d\n", a, b, d);
    printf("He so x, y: x = %d, y = %d\n", x, y);
    printf("%d*%d + %d*%d = %d\n", a, x, b, y, d);

    return 0;
}
```

